export const CATEGORIES = ['seo', 'performance', 'accessibility', 'technical', 'content'];

export const CATEGORY_LABELS = {
  en: { seo: 'SEO', performance: 'Performance', accessibility: 'Accessibility', technical: 'Technical', content: 'Content' },
  fr: { seo: 'SEO', performance: 'Performance', accessibility: 'Accessibilité', technical: 'Technique', content: 'Contenu' },
};

const FIELDS = ['label', 'title', 'explanation', 'impact', 'fix', 'example'];

/** Returns the texts of a check in the requested language, with {placeholders} filled. */
export function describe(id, lang = 'en', values = {}) {
  const entry = CATALOG[id];
  if (!entry) return null;
  const arr = entry[lang] || entry.en;
  const out = {};
  FIELDS.forEach((field, i) => {
    out[field] = (arr[i] || '').replace(/\{(\w+)\}/g, (m, key) => (values[key] !== undefined ? String(values[key]) : m));
  });
  return out;
}
